import{_ as a,o as i,c as n,a2 as r}from"./chunks/framework.DQhM5RF8.js";const m=JSON.parse('{"title":"Land Claims & Siege Mechanics","description":"","frontmatter":{},"headers":[],"relativePath":"info/claims-siege.md","filePath":"info/claims-siege.md"}'),s={name:"info/claims-siege.md"};function o(t,e,l,c,d,g){return i(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="land-claims-siege-mechanics" tabindex="-1">Land Claims &amp; Siege Mechanics <a class="header-anchor" href="#land-claims-siege-mechanics" aria-label="Permalink to &quot;Land Claims &amp; Siege Mechanics&quot;">​</a></h1><p>Understanding how base defense, territory expansion, and active siege windows function on LlamaCraft.</p><hr><h2 id="_1-land-claim-basics-griefprevention" tabindex="-1">1. Land Claim Basics (GriefPrevention) <a class="header-anchor" href="#_1-land-claim-basics-griefprevention" aria-label="Permalink to &quot;1. Land Claim Basics (GriefPrevention)&quot;">​</a></h2><p>Every player begins with <strong>100 free claim blocks</strong> and automatically earns <strong>100 additional claim blocks for every hour played</strong> on the server.</p><h3 id="creating-your-first-claim" tabindex="-1">Creating Your First Claim <a class="header-anchor" href="#creating-your-first-claim" aria-label="Permalink to &quot;Creating Your First Claim&quot;">​</a></h3><ol><li>Equip a <strong>Golden Shovel</strong> (given in your <code>/kit starter</code> or crafted).</li><li>Right-click one corner block of the area you wish to protect. A diamond block indicator will appear.</li><li>Walk diagonally across to the opposite corner and right-click the second block.</li><li>Gold and glowstone boundary blocks will visualize your protected cuboid.</li></ol><h3 id="trust-levels" tabindex="-1">Trust Levels <a class="header-anchor" href="#trust-levels" aria-label="Permalink to &quot;Trust Levels&quot;">​</a></h3><ul><li><strong>Access Trust</strong> (<code>/accesstrust &lt;player&gt;</code>): Can open wooden doors, trapdoors, gates, and press buttons.</li><li><strong>Container Trust</strong> (<code>/containertrust &lt;player&gt;</code>): Can open chests, barrels, shulker boxes, furnaces, and hoppers.</li><li><strong>Build Trust</strong> (<code>/trust &lt;player&gt;</code>): Can place and break blocks, build redstone, and access all containers.</li><li><strong>Permission Trust</strong> (<code>/permissiontrust &lt;player&gt;</code>): Can assign trust levels to others inside your claim.</li></ul><hr><h2 id="_2-siege-mechanics-raiding-windows" tabindex="-1">2. Siege Mechanics &amp; Raiding Windows <a class="header-anchor" href="#_2-siege-mechanics-raiding-windows" aria-label="Permalink to &quot;2. Siege Mechanics &amp; Raiding Windows&quot;">​</a></h2><p>LlamaCraft runs a balanced raid cycle powered by <strong>SiegeTime</strong>. Rather than allowing 24/7 offline destruction, raiding is concentrated into designated active siege windows.</p><h3 id="rules-of-engagement" tabindex="-1">Rules of Engagement <a class="header-anchor" href="#rules-of-engagement" aria-label="Permalink to &quot;Rules of Engagement&quot;">​</a></h3><ul><li><strong>Active Siege Windows</strong>: During scheduled siege windows, explosions (TNT, End Crystals, TNT cannons) and pistons remain active everywhere, including unclaimed wilderness and unshielded enemy claims.</li><li><strong>Admin Claim Immunity</strong>: Spawn hubs, road corridors, and community landmarks are under permanent Admin Claims and can never be altered or blown up.</li><li><strong>Siege Shields</strong> (<code>/siegeshield</code>): Clans can purchase timed shields using economy currency to protect their territory while members are offline.</li><li><strong>Defender Re-spawn Protection</strong>: Defenders who die inside their own besieged claim receive a 3-minute grace respawn period to regroup.</li></ul>',14)])])}const h=a(s,[["render",o]]);export{m as __pageData,h as default};
